@private_bp.before_request
def check_authorization():
    start_time = time.time()
    token = request.headers.get('Authorization')
    userID = request.view_args.get('userID') if request.view_args else request.args.get('userID')

    if not userID:
        return jsonify({"return_code": "KO error", "error": "Missing parameter userID", "received": request.args}), 400

    if not token:
        return jsonify({"return_code": "KO error","error": "Authorization header missing"}), 401
    else:
        g.token = token
        token = request.headers.get('Authorization')
        token = token.split(' ')[-1] if token else None

        if token is None or str(token) == "undefined" or str(token) == "null":
            return jsonify({"return_code": "KO error", "error": "invalid token"}), 401

        token_introspection = introspect_token("FRMBAU01.ecom.local", "8080", "master", token, "BNeMJlqVcA2SbbIqq9SJtfqmmMKL5s8n", "apiconnect")
        if 'error' in token_introspection:
            return jsonify({"return_code": "KO error", "error": "invalid token"}), 500

        validated = inspect_introspect_response(token_introspection, userID)

        if not validated.get("active"):
            return jsonify({"return_code": "KO error", "error": "invalid token"}), 401

    if not validated.get("is_username_the_same"):
        return jsonify({"return_code": "KO error", "error": "invalid token"}), 401

    g.userID = userID
    g.token_info = validated

